import heapq

def match(orders):
    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    info = {}       # id -> dict(side, price, qty, seq, active)
    trades = []
    seq_counter = 0

    def add_to_book(oid):
        d = info[oid]
        if d['side'] == 'buy':
            heapq.heappush(buy_heap, (-d['price'], d['seq'], oid))
        else:
            heapq.heappush(sell_heap, (d['price'], d['seq'], oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in info and info[oid]['active'] and info[oid]['qty'] > 0:
                info[oid]['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]
            opp_d = info.get(opp_id)
            if opp_d is None or not opp_d['active'] or opp_d['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            opp_price = opp_d['price']

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            # perform trade
            heapq.heappop(opp_heap)
            trade_qty = min(remaining, opp_d['qty'])

            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp_d['qty'] -= trade_qty

            if opp_d['qty'] > 0:
                heapq.heappush(opp_heap, top)
            else:
                opp_d['active'] = False

        if typ == 'limit':
            info[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'seq': my_seq,
                'active': remaining > 0
            }
            if remaining > 0:
                add_to_book(oid)
        # for 'ioc' and 'market', any remaining quantity is discarded
        # and we do not add an entry to info (so later cancels do nothing)

    return trades

